import logging
from unittest.mock import MagicMock, patch

import pytest

from agentic_rag.middleware.logging import audit_logging_middleware, get_tracker, set_tracker
from agentic_rag.token_tracker import TokenTracker


class TestSetTracker:
    """Tests for set_tracker function."""

    def test_set_and_get_tracker(self):
        """Test setting and getting tracker."""
        tracker = TokenTracker("gpt-4.1-mini")
        set_tracker(tracker)
        assert get_tracker() is tracker

    def test_get_tracker_none_by_default(self):
        """Test get_tracker returns None when not set."""
        set_tracker(None)
        assert get_tracker() is None


class TestAuditLoggingMiddleware:
    """Tests for audit_logging_middleware."""

    def setup_method(self):
        """Reset tracker before each test."""
        set_tracker(None)

    def test_middleware_logs_tool_call(self, caplog):
        """Test middleware logs tool call."""
        request = MagicMock()
        request.tool_call = {"name": "test_tool", "args": {"arg1": "value1"}}

        def handler(req):
            return "result"

        with caplog.at_level(logging.INFO, logger="agentic_rag.tools"):
            result = audit_logging_middleware(request, handler)

        assert result == "result"
        assert "TOOL CALL: test_tool" in caplog.text
        assert "TOOL RESULT: test_tool completed" in caplog.text

    def test_middleware_logs_duration(self, caplog):
        """Test middleware logs duration."""
        request = MagicMock()
        request.tool_call = {"name": "slow_tool", "args": {}}

        def handler(req):
            import time
            time.sleep(0.1)
            return "result"

        with caplog.at_level(logging.INFO, logger="agentic_rag.tools"):
            audit_logging_middleware(request, handler)

        assert "completed in" in caplog.text

    def test_middleware_logs_error(self, caplog):
        """Test middleware logs error on exception."""
        request = MagicMock()
        request.tool_call = {"name": "failing_tool", "args": {}}

        def handler(req):
            raise ValueError("test error")

        with caplog.at_level(logging.ERROR, logger="agentic_rag.tools"):
            with pytest.raises(ValueError):
                audit_logging_middleware(request, handler)

        assert "TOOL ERROR: failing_tool failed" in caplog.text

    def test_middleware_tracks_tokens_when_tracker_set(self):
        """Test middleware tracks tokens when tracker is set."""
        tracker = TokenTracker("gpt-4.1-mini")
        set_tracker(tracker)

        request = MagicMock()
        request.tool_call = {"name": "llm_tool", "args": {}}

        def handler(req):
            result = MagicMock()
            result.response_metadata = {
                "token_usage": {
                    "prompt_tokens": 100,
                    "completion_tokens": 50,
                }
            }
            return result

        audit_logging_middleware(request, handler)

        assert tracker.call_count == 1
        summary = tracker.get_summary()
        assert summary.input_tokens == 100
        assert summary.output_tokens == 50

    def test_middleware_no_tracking_without_tracker(self):
        """Test middleware works without tracker."""
        set_tracker(None)

        request = MagicMock()
        request.tool_call = {"name": "tool", "args": {}}

        def handler(req):
            return "result"

        result = audit_logging_middleware(request, handler)
        assert result == "result"

    def test_middleware_no_tracking_without_token_usage(self):
        """Test middleware works when result has no token usage."""
        tracker = TokenTracker("gpt-4.1-mini")
        set_tracker(tracker)

        request = MagicMock()
        request.tool_call = {"name": "tool", "args": {}}

        def handler(req):
            result = MagicMock()
            result.response_metadata = {}
            return result

        audit_logging_middleware(request, handler)

        assert tracker.call_count == 0
